  border-style: solid;
  border-width: thin 0 0 0;
}
.v-divider--vertical {
  align-self: stretch;
  border-width: 0 thin 0 0;
  display: inline-flex;
  height: auto;
  margin-left: -1px;
  max-height: 100%;
  max-width: 0px;
  vertical-align: text-bottom;
  width: 0px;
}
.v-divider--inset:not(.v-divider--vertical) {
  max-width: calc(100% - 72px);
  margin-inline-start: 72px;
}
